{"file_path":"C:\Users\wk\WorkBuddy\2026-10-17-16-25-00\.workbuddy\tmp-clip-find.ps1","content":"$ErrorActionPreference = 'Continue'
$out = Join-Path $PSScriptRoot 'tmp-clip-find.txt'
Set-Content -LiteralPath $out -Value 'FIND' -Encoding UTF8
function Add-Line([string]$s) { Add-Content -LiteralPath $out -Value $s -Encoding UTF8 }

$needle = 'hlg_[REDACTED]'
$roots = @(
    "$env:USERPROFILE\Desktop",
    "$env:USERPROFILE\Documents",
    "$env:USERPROFILE\Downloads",
    "$env:APPDATA",
    "$env:LOCALAPPDATA"
)
$exts = '*.txt','*.json','*.log','*.md','*.csv','*.xml','*.ini','*.cfg','*.conf','*.html','*.htm'
foreach ($root in $roots) {
    if (-not (Test-Path -LiteralPath $root)) { continue }
    Add-Line ('ROOT ' + $root)
    Get-ChildItem -LiteralPath $root -Recurse -Force -Include $exts -ErrorAction SilentlyContinue |
        Where-Object { -not $_.PSIsContainer -and $_.Length -lt 5MB -and $_.LastWriteTime -gt (Get-Date).AddDays(-14) } |
        Select-Object -First 400 |
        ForEach-Object {
            $hit = Select-String -LiteralPath $_.FullName -Pattern $needle -SimpleMatch -List -ErrorAction SilentlyContinue
            if ($hit) { Add-Line ('HIT ' + $_.FullName) }
        }
}
Add-Line 'DONE'
"}

