import os,time,glob
roots=[r'D:\doDesk',r'D:\uu远程',r'E:\Tencent\Ardot',r'C:\Users\wk\AppData\Local\ToDesk',r'C:\Users\wk\AppData\Roaming\ToDesk']
recent=[]
now=time.time()
for r in roots:
    if not os.path.isdir(r): continue
    for dp,dn,fn in os.walk(r):
        for f in fn:
            fp=os.path.join(dp,f)
            try:
                st=os.stat(fp)
            except OSError: continue
            if now-st.st_mtime<3600 and st.st_size>0:
                recent.append((st.st_mtime,fp,st.st_size))
recent.sort(reverse=True)
print('recent files in last hour:',len(recent))
for m,fp,sz in recent[:25]:
    print(time.strftime('%H:%M:%S',time.localtime(m)),sz,fp)
