{"content": "# 剪贴板“自动改写”复测脚本
# 用法：先复制那段 hlg_ 开头的文本，然后双击「剪贴板诊断.bat」
# 脚本会把剪贴板里现有的内容原样再写一次，观察 1.2 秒内是否被别的程序改掉。

$ErrorActionPreference = 'Stop'

function Show([string]$label, [string]$text) {
    $len = if ($null -eq $text) { 0 } else { $text.Length }
    $head = if ($len -gt 12) { $text.Substring(0, 12) } else { $text }
    $tail = if ($len -gt 8) { $text.Substring($len - 8) } else { "" }
    Write-Host ("{0,-10} 长度={1}  头={2}  尾={3}" -f $label, $len, $head, $tail)
}

$orig = Get-Clipboard -Raw
if ([string]::IsNullOrWhiteSpace($orig)) {
    Write-Host "剪贴板是空的。请先复制那段要测试的文本，再运行本脚本。" -ForegroundColor Yellow
    return
}

Write-Host "=== 第 1 步：记录当前剪贴板 ===" -ForegroundColor Cyan
Show "原始" $orig
Write-Host ""

$changed = 0
for ($i = 1; $i -le 3; $i++) {
    Set-Clipboard -Value $orig
    Start-Sleep -Milliseconds 1200
    $after = Get-Clipboard -Raw
    if ($after -ne $orig) {
        $changed++
        Write-Host ("=== 第 {0} 次：被改写 ===" -f ($i + 1)) -ForegroundColor Red
        Show " 改写后" $after
    } else {
        Write-Host ("=== 第 {0} 次：未被改写 ===" -f ($i + 1)) -ForegroundColor Green
    }
}

Write-Host ""
if ($changed -gt 0) {
    Write-Host "结论：本机有常驻程序在监听剪贴板，并会把这类文本替换成另一个版本。" -ForegroundColor Red
    Write-Host "对照方法：完全退出 WorkBuddy（右下角托盘也退出）后再运行本脚本；如仍被改写，说明与 WorkBuddy 无关。" -ForegroundColor Yellow
} else {
    Write-Host "结论：这次没有被改写。可对照测试：关闭远程控制软件（ToDesk / UU远程）的“剪贴板同步”后再试。" -ForegroundColor Yellow
}
