{"content": "import ctypes, ctypes.wintypes as wt, os, json, sys

k32 = ctypes.WinDLL('kernel32', use_last_error=True)
ntdll = ctypes.WinDLL('ntdll', use_last_error=True)

k32.OpenProcess.argtypes = [wt.DWORD, wt.BOOL, wt.DWORD]
k32.OpenProcess.restype = wt.HANDLE
k32.CloseHandle.argtypes = [wt.HANDLE]
ntdll.NtResumeProcess.argtypes = [wt.HANDLE]
ntdll.NtResumeProcess.restype = ctypes.c_long

STATE = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'tmp-suspended.json')

n = 0
if os.path.exists(STATE):
    try:
        with open(STATE) as f:
            lst = json.load(f)
    except Exception:
        lst = []
    for pid in lst:
        h = k32.OpenProcess(0x0800, False, pid)
        if not h:
            continue
        try:
            if ntdll.NtResumeProcess(h) == 0:
                n += 1
        finally:
            k32.CloseHandle(h)
    try:
        os.remove(STATE)
    except OSError:
        pass
    print('resumed %d processes' % n)
else:
    print('no state file, nothing to do')
", "file_path": "C:\Users\wk\WorkBuddy\2026-10-17-16-25-00\tmp-resume.py"}

