import sqlite3, shutil, os, datetime, glob
def conv(us):
    try: return (datetime.datetime(1601,1,1)+datetime.timedelta(microseconds=int(us))).strftime('%Y-%m-%d %H:%M')
    except Exception: return '?'
cands = []
