    h = os.path.join(prof,'History')
    if os.path.isfile(h): cands.append(('Chrome',h))
for prof in glob.glob(os.path.expanduser('~')+r'\AppData\Local\Microsoft\Edge\User Data\*'):
    h = os.path.join(prof,'History')
