for name, h in cands:
    tmp = 'tmp-hist.db'
    try:
        shutil.copy2(h, tmp)
    except Exception as e:
        print(name, 'copy fail', e); continue
    try:
        con = sqlite3.connect(tmp)
        cur = con.cursor()
        cur.execute('select target_path, tab_url, start_time, received_bytes from downloads order by start_time desc limit 400')
        rows = cur.fetchall()
        print('\n=== %s downloads total=%d ===' % (name, len(rows)))
