            d = conv(ts)
            if d.startswith('2026-04') or d.startswith('2026-03'):
                print('  %s  %10s  %s' % (d, sz, (tp or '')[:100]))
                print('        from %s' % (url or '')[:120])
        con.close()
    finally:
        try: os.remove(tmp)
        except OSError: pass
