{"content": """"共享配置与路径解析。

样本目录的解析顺序：
1. 同目录 config.json 里的 sample_dirs
2. 同目录 samples/ 子目录（其下每个子目录各算一个样本组；若直接平铺文件则整体算一组）
3. 内置默认：原始隔离目录

想换机器/换路径，只改 config.json 即可，脚本本身不用动。
"""
import os
import json
import pathlib

HERE = pathlib.Path(__file__).resolve().parent
CONFIG = HERE / 'config.json'

DEFAULT_DIRS = [
    r'C:\Users\wk\AppData\Roaming\comain_ev2c34.QUARANTINE_20261018',
    r'C:\Users\wk\AppData\Roaming\comain_ev2f79.QUARANTINE_20261018',
]


def sample_dirs():
    if CONFIG.exists():
        try:
            cfg = json.loads(CONFIG.read_text(encoding='utf-8'))
            dirs = [p for p in cfg.get('sample_dirs', []) if p]
            if dirs:
                return dirs
        except Exception:
            pass

    local = HERE / 'samples'
    if local.is_dir():
        subs = [str(p) for p in sorted(local.iterdir()) if p.is_dir()]
        return subs if subs else [str(local)]

    return list(DEFAULT_DIRS)


def _walk():
    out = []
    for d in sample_dirs():
        if not os.path.isdir(d):
            continue
        for fn in sorted(os.listdir(d)):
            fp = os.path.join(d, fn)
            if os.path.isfile(fp):
                out.append(fp)
    return out


def all_files():
    return _walk()


def blobs():
    return [p for p in _walk() if not p.lower().endswith('.exe')]


def exes():
    return [p for p in _walk() if p.lower().endswith('.exe')]


def find(name):
    for p in _walk():
        if os.path.basename(p).lower() == name.lower():
            return p
    return None


def status():
    dirs = sample_dirs()
    lines = ['样本目录:']
    for d in dirs:
        ok = os.path.isdir(d)
        n = len([f for f in os.listdir(d)]) if ok else 0
        lines.append('  [%s] %s  (%d 个条目)' % ('OK' if ok else 'MISSING', d, n))
    return '\n'.join(lines)


if __name__ == '__main__':
    print(status())
    print('blobs: %d   exes: %d' % (len(blobs()), len(exes())))
