      $sig = (Get-AuthenticodeSignature -LiteralPath $f).Status
      Write-Output ("  [非系统] " + $f + "  sig=" + $sig)
      $bad++
    }
  }
  if($bad -eq 0){ Write-Output "  (全部位于 Windows 目录)" }
  Write-Output ("  模块总数: " + $p.Modules.Count)
}
