{"command": "$ErrorActionPreference='SilentlyContinue'
$win = $env:WINDIR
Write-Output "===== 1) drivers 目录里 2026-04-01 之后变化的 .sys ====="
Get-ChildItem (Join-Path $win 'System32\drivers') -Filter *.sys -File |
  Where-Object { $_.LastWriteTime -gt (Get-Date '2026-04-01') } |
  Sort-Object LastWriteTime |
  ForEach-Object {
    $sig = (Get-AuthenticodeSignature -LiteralPath $_.FullName).Status
    Write-Output ("  " + $_.LastWriteTime.ToString('yyyy-MM-dd HH:mm') + "  " + $_.Length.ToString().PadLeft(8) + "B  sig=" + $sig + "  " + $_.Name)
  }
Write-Output ""
Write-Output "===== 2) 2025-06-01 之后新增的 .sys（drivers + DriverStore，前 15）====="
foreach($r in @((Join-Path $win 'System32\drivers'), (Join-Path $win 'System32\DriverStore\FileRepository'))){
  Get-ChildItem $r -Filter *.sys -File -Recurse -ErrorAction SilentlyContinue |
    Where-Object { $_.LastWriteTime -gt (Get-Date '2025-06-01') } |
    Sort-Object LastWriteTime -Descending | Select-Object -First 15 |
    ForEach-Object { Write-Output ("  " + $_.LastWriteTime.ToString('yyyy-MM-dd HH:mm') + "  " + $_.FullName) }
}
Write-Output ""
Write-Output "===== 3) 运行中的驱动：非微软签名 / 文件缺失 ====="
$tot = 0; $nonms = 0
Get-CimInstance Win32_SystemDriver | Where-Object { $_.State -eq 'Running' } | ForEach-Object {
  $tot++
  if(-not $_.PathName){ return }
  $p = $_.PathName -replace '^\?\?\\',''
  $p = $p -replace '^\\SystemRoot\\', ($win + '\')
  $p = $p -replace '^System32\\', ($win + '\System32\')
  if(Test-Path -LiteralPath $p){
    $s = Get-AuthenticodeSignature -LiteralPath $p
    $subj = if($s.SignerCertificate){$s.SignerCertificate.Subject}else{''}
    if($subj -notmatch 'Microsoft'){
      $nonms++
      Write-Output ("  [非MS] " + $_.Name + "  sig=" + $s.Status + "  " + $subj)
      Write-Output ("         -> " + $p)
    }
  } else {
    Write-Output ("  [文件缺失] " + $_.Name + "  -> " + $_.PathName)
  }
}
Write-Output ("  Running 驱动总数=" + $tot + "  其中非微软签名=" + $nonms)", "description": "扫描异常内核驱动（修正语法）"}

