Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services' | ForEach-Object {
  $ip = (Get-ItemProperty $_.PSPath).ImagePath
  if($ip -and $ip -notmatch '(?i)^"?\\?\??[A-Z]?:?\\?(Windows|SystemRoot)') {
    if($ip -notmatch '(?i)system32|syswow64') {
      $svc = $_.PSChildName
      if($svc -notmatch '^(ACPI|asw|BITS|cdrom|disk|Dnscache|EventLog|gpsvc|HTTP|LanmanServer|LanmanWorkstation)') {
