Write-Output "===== 2) ServiceDll 不在 System32 或签名异常 ====="
Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services' | ForEach-Object {
  $svc = $_.PSChildName
  $p = Join-Path $_.PSPath 'Parameters'
  $dll = (Get-ItemProperty $p).ServiceDll
  if($dll){
    $d = $dll -replace '^\\\?\?\\',''
    $d = $d -replace '^\\SystemRoot\\', ($win + '\')
    if($d -notmatch '(?i)Windows\\(System32|SysWOW64)' -or -not (Test-Path -LiteralPath $d)){
      $sig = if(Test-Path -LiteralPath $d){(Get-AuthenticodeSignature -LiteralPath $d).Status}else{'MISSING'}
